// Fills a deployment with demo data and photographs every screen the guides show.
//
// The guides in docs/ are only worth reading if their figures are this product.
// So there is no fixture directory and no mockup here: the script talks to a
// real control plane over the same REST API the console uses, then drives the
// console itself with a browser. Whatever the screen renders is what lands in
// docs/screenshots/guide/.
//
// The data is deliberately invented — 데모물산, 홍길동, example.com — because a
// figure is published and a real name, a real host or a real secret published in
// a PDF cannot be taken back.
//
// This script writes. It fills the deployment with demo agents and keys, and it
// replaces four settings that are global to the whole platform — the policy
// document, the content-inspection rules, the session gateway and tracking.
// So it refuses to guess its target: there is no default URL, the variables are its own rather
// than the AGENTHUB_TEST_* pair the e2e scripts share, and it will not start
// without being told in writing that the deployment is disposable. It also puts
// the four global settings back the way it found them on the way out, and one
// restoration that fails is reported rather than abandoning the other three.
// Every REST call it makes carries a deadline — AGENTHUB_GUIDE_REQUEST_TIMEOUT_MS,
// 30000 by default — so a control plane that stops answering ends the run
// through that restoration instead of holding it open forever.
//
//   AGENTHUB_GUIDE_URL=http://127.0.0.1:8080 \
//   AGENTHUB_GUIDE_USER=admin AGENTHUB_GUIDE_PASSWORD=… \
//   AGENTHUB_GUIDE_DISPOSABLE=yes \
//   node scripts/guide-shots.mjs
//
// The run history and the task queue are photographed with work in them when a
// worker is attached to the same database and AGENTHUB_GUIDE_MODEL_URL names a
// model endpoint it can reach — scripts/guide-model-stub.mjs answers the seeded
// tasks in the shape the worker expects. The seeded models point there while the
// tasks execute and are moved back to their display address before the first
// picture, so the runs are the worker's own and the figures still show the
// in-house hostname a reader would see. Without it the tasks stay queued and
// those two screens are photographed empty, as they were.
import { chromium } from 'playwright-core'
import { mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { chromiumPath } from './browser.mjs'
import { withGuideSettings } from './guide-settings-check.mjs'

const baseURL = (process.env.AGENTHUB_GUIDE_URL ?? '').replace(/\/$/, '')
const username = process.env.AGENTHUB_GUIDE_USER ?? ''
const password = process.env.AGENTHUB_GUIDE_PASSWORD ?? ''
if (!baseURL || !username || !password) {
  console.error('AGENTHUB_GUIDE_URL, AGENTHUB_GUIDE_USER, AGENTHUB_GUIDE_PASSWORD 이 모두 필요합니다.')
  console.error('이 스크립트는 정책·내용 검사·세션 게이트웨이·방문 추적을 덮어씁니다. 대상을 짐작하지 않습니다.')
  process.exit(2)
}
if (process.env.AGENTHUB_GUIDE_DISPOSABLE !== 'yes') {
  console.error(`${baseURL} 의 전역 설정(정책·내용 검사·세션 게이트웨이·방문 추적)을 덮어씁니다.`)
  console.error('버려도 되는 배포가 맞으면 AGENTHUB_GUIDE_DISPOSABLE=yes 를 주고 다시 실행하세요.')
  process.exit(2)
}
const here = dirname(fileURLToPath(import.meta.url))
const shotDir = process.env.GUIDE_SHOT_DIR ?? join(here, '..', '..', 'docs', 'screenshots', 'guide')
// Where the worker finds a model while the seeded tasks execute; empty means no
// worker is attached and the tasks are left queued.
const modelURL = (process.env.AGENTHUB_GUIDE_MODEL_URL ?? '').replace(/\/$/, '')
// The address the figures show. It is a hostname, not a place, on purpose.
const displayModelURL = 'https://llm.example.internal/v1'
mkdirSync(shotDir, { recursive: true })

const problems = []
const note = (label, ok, detail = '') => {
  console.log(`${ok ? '  ok  ' : ' FAIL '} ${label}${detail ? ` — ${detail}` : ''}`)
  if (!ok) problems.push(`${label}${detail ? `: ${detail}` : ''}`)
}

const browser = await chromium.launch({ executablePath: chromiumPath(), headless: true, args: ['--no-sandbox'] })
try {
  // 1440x900 is the desktop size the guide standard fixes. deviceScaleFactor 2
  // keeps the Korean text readable once the PDF scales the figure down.
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2, locale: 'ko-KR' })
  const page = await context.newPage()

  await page.goto(baseURL, { waitUntil: 'networkidle' })
  await page.getByLabel('아이디').fill(username)
  await page.getByLabel('비밀번호').fill('')
  await shoot(page, 'login', '로그인 화면')

  await page.getByLabel('비밀번호').fill(password)
  await page.getByRole('button', { name: '로그인', exact: true }).click()
  await page.getByRole('heading', { name: new RegExp(`${username}님`) }).waitFor({ timeout: 30000 })

  // A control plane that accepts the connection but never answers would own the
  // whole shoot: fetch has no deadline of its own and neither has page.evaluate,
  // so one stalled request would strand the run inside withGuideSettings with
  // the four global settings left on the demo values. Every call here is a
  // single admin REST request — the long waits of a shoot belong to page.goto,
  // shoot and settle, not to these — so thirty seconds is already generous.
  const requestTimeoutMs = Number(process.env.AGENTHUB_GUIDE_REQUEST_TIMEOUT_MS) || 30000
  const call = async (method, path, body) => {
    // page.evaluate serialises this function into the browser, so the deadline
    // travels in the argument array rather than as a closure variable.
    const result = await page.evaluate(async ([method, path, body, timeoutMs]) => {
      const csrf = document.cookie.split('; ').find((c) => c.startsWith('agenthub_csrf='))
      const headers = { 'Content-Type': 'application/json' }
      if (csrf) headers['X-CSRF-Token'] = decodeURIComponent(csrf.split('=').slice(1).join('='))
      try {
        const response = await fetch(path, { method, credentials: 'include', headers, body: body === null ? undefined : JSON.stringify(body), signal: AbortSignal.timeout(timeoutMs) })
        const text = await response.text()
        let parsed = null
        let parseError = false
        try { parsed = text ? JSON.parse(text) : null } catch { parseError = true }
        return { status: response.status, body: parsed, parseError }
      } catch (error) {
        // The abort is a DOMException in here. Name it where it is still one,
        // rather than reading a serialised message on the other side.
        if (error?.name === 'TimeoutError' || error?.name === 'AbortError') return { timedOut: true }
        throw error
      }
    }, [method, path, body ?? null, requestTimeoutMs])
    // Which call was cut matters as much as the fact, because this one is read
    // in a log after the run gave up.
    if (result.timedOut) throw new Error(`${method} ${path} 가 ${requestTimeoutMs}ms 안에 응답하지 않음`)
    return result
  }
  const get = (path) => call('GET', path)
  const post = (path, body) => call('POST', path, body)
  const put = (path, body) => call('PUT', path, body)
  const del = (path) => call('DELETE', path)
  const ok = (response) => response.status >= 200 && response.status < 300

  // Back up all four global settings before seed or tracking can write.
  // GUIDE_SKIP_SEED only re-photographs the existing deployment.
  await withGuideSettings(call, {
    skipSeed: process.env.GUIDE_SKIP_SEED === '1',
    seed: () => seed({ get, post, put, ok }),
    capture: () => capture(page),
    captureTracking: () => captureTracking(page, { put, del, ok }),
    note,
  })

  if (problems.length) {
    console.log(`\n${problems.length}건이 계획대로 되지 않았습니다:`)
    for (const problem of problems) console.log(`  - ${problem}`)
    process.exitCode = 1
  } else {
    console.log(`\n캡처 완료 — ${shotDir}`)
  }
} finally {
  await browser.close()
}

/** shoot waits for the screen to settle and writes one figure. */
async function shoot(page, name, label) {
  // A spinner frozen into a figure is the one thing the standard calls out, so
  // the wait is for the network to go quiet and then for a paint to land.
  await page.waitForLoadState('networkidle').catch(() => {})
  await page.waitForTimeout(700)
  await page.screenshot({ path: join(shotDir, `${name}.png`) })
  note(`${label} → ${name}.png`, true)
}

/** visit opens a console route and photographs it. */
async function visit(page, route, name, label, prepare) {
  await page.goto(`${baseURL}${route}`, { waitUntil: 'networkidle' })
  if (prepare) {
    try {
      await prepare(page)
    } catch (error) {
      note(`${label} 준비`, false, String(error).slice(0, 160))
    }
  }
  await shoot(page, name, label)
}

/**
 * captureTracking photographs the visitor-tracking tab with Momento configured
 * through the same-origin proxy and one blocked origin on the list. It runs
 * last and switches tracking off again on the way out: while it is on every
 * page carries the snippet, and the tracker it points at does not exist here.
 * The generic restore then puts back whatever the deployment held before.
 */
async function captureTracking(page, { put, del, ok }) {
  const settings = { enabled: true, provider: 'momento', momentoUrl: 'https://momento.example.internal', momentoSiteId: 'agenthub', momentoProxy: true, momentoEnvironment: 'prd', placement: 'head', includeAdmin: false, allowedHosts: '', customSnippet: '' }
  const saved = await put('/api/v1/admin/settings/tracking', { value: settings })
  note('방문 추적 설정', ok(saved), `HTTP ${saved.status}`)
  // What a browser posts when the policy refuses a request — here a pixel the
  // snippet did not name, which is the case the list exists for.
  const report = await page.evaluate(async () => {
    const response = await fetch('/api/v1/tracking/csp-report', { method: 'POST', headers: { 'Content-Type': 'application/csp-report' },
      body: JSON.stringify({ 'csp-report': { 'document-uri': `${location.origin}/runs`, 'blocked-uri': 'https://pixel.example.internal/p.gif', 'effective-directive': 'img-src', 'violated-directive': "img-src 'self' data:" } }) })
    return response.status
  })
  note('정책 위반 신고', report === 204, `HTTP ${report}`)
  try {
    await visit(page, '/admin/settings', 'admin-settings-tracking', '관리자 · 전역 설정 · 방문 추적', async (page) => {
      await page.getByRole('button', { name: 'Tracking' }).click()
      await page.locator('.violation-row').first().waitFor({ timeout: 10000 })
    })
    // The blocked-origin list sits below the form; the reader is sent to it.
    await page.locator('.violation-list').scrollIntoViewIfNeeded()
    await shoot(page, 'admin-settings-tracking-blocked', '관리자 · 전역 설정 · 방문 추적 · 차단된 출처')
  } finally {
    const off = await put('/api/v1/admin/settings/tracking', { value: { ...settings, enabled: false } })
    note('방문 추적 끄기', ok(off), `HTTP ${off.status}`)
    // The report above is this script's, not the deployment's.
    await del('/api/v1/admin/tracking/violations')
  }
}
const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value)
const globals = [
  ['policy', '/api/v1/admin/policy', 'document', value => isObject(value) && Array.isArray(value.rules)],
  ['dlp', '/api/v1/admin/dlp', 'settings', value => isObject(value) && typeof value.enabled === 'boolean'
    && (!Object.hasOwn(value, 'classes') || isObject(value.classes))],
  ['sessionGateway', '/api/v1/admin/settings', 'sessionGateway', isObject],
  ['tracking', '/api/v1/admin/settings', 'tracking', isObject],
]

// All four API values must be restorable before any work starts. There is no
// setting deletion API, so an absent gateway/tracker cannot safely be seeded.
export async function withGuideSettings(call, { seed, capture, captureTracking, skipSeed = false, note = () => {} }) {
  if (skipSeed) return await capture()

  const before = []
  for (const [name, readPath, key, valid] of globals) {
    let response
    try {
      response = await call('GET', readPath)
    } catch (cause) {
      throw new Error(`${name} backup failed: ${cause.message}`, { cause })
    }
    if (!Number.isInteger(response?.status) || response.status < 200 || response.status >= 300) {
      throw new Error(`${name} backup failed: HTTP ${response?.status ?? 'unknown'}`)
    }
    if (response.parseError) throw new Error(`${name} backup failed: invalid JSON`)
    if (!isObject(response.body) || !valid(response.body[key])) {
      throw new Error(`${name} backup failed: missing or invalid ${key}`)
    }
    const value = structuredClone(response.body[key])
    before.push(readPath === '/api/v1/admin/settings'
      ? [`${readPath}/${key}`, { value }]
      : [readPath, value])
  }

  let failedWork = false
  try {
    await seed()
    await capture()
    await captureTracking()
  } catch (error) {
    failedWork = true
    throw error
  } finally {
    // A failed write may already have reached the server. Keep all work inside
    // this restoration boundary, but never enter it with an incomplete backup.
    // One call that rejects — a restarted control plane, a closed page — must
    // not leave the settings behind it on the demo values, so every restoration
    // is attempted and its failure recorded rather than thrown from the loop.
    const failed = []
    for (const [path, value] of before) {
      let ok = false, detail
      try {
        const restored = await call('PUT', path, value)
        ok = restored.status >= 200 && restored.status < 300
        detail = `HTTP ${restored.status}`
      } catch (cause) {
        detail = cause.message
      }
      note(`복원 ${path}`, ok, detail)
      if (!ok) failed.push(`${path} (${detail})`)
    }
    // What the run was doing when it broke matters more than the way out, so a
    // failure here is only raised when the work itself got through.
    if (failed.length && !failedWork) throw new Error(`복원 실패: ${failed.join(', ')}`)
  }
}
import test from 'node:test'
import assert from 'node:assert/strict'
import { readFile } from 'node:fs/promises'
import vm from 'node:vm'

const source = await readFile(new URL('./guide-shots.mjs', import.meta.url), 'utf8')
// The real script is cut out and run, so anything call depends on — the request
// deadline included — has to sit inside these two anchors.
const boundary = source.slice(source.indexOf('  const requestTimeoutMs ='), source.indexOf('  if (problems.length)'))
const imports = source.match(/import \{ withGuideSettings \} from '(.*?)'/)
const helper = imports ? await import(new URL(imports[1], import.meta.url)) : {}
const paths = ['/api/v1/admin/policy', '/api/v1/admin/dlp', '/api/v1/admin/settings', '/api/v1/admin/settings']
const keys = ['document', 'settings', 'sessionGateway', 'tracking']
function originals() {
  return [
    { document: { rules: [{ id: 'original', actions: ['tool.call'] }], defaultEffect: 'allow' } },
    { settings: { enabled: false, classes: { phone: 'audit' }, scanResponses: true } },
    { sessionGateway: { enabled: false, extra: { list: ['original'] } }, tracking: { enabled: false, extra: { list: ['original'] } } },
  ]
}
// A stalled control plane accepts the request and then says nothing. Only the
// deadline the caller attached can end it, so the stub settles on abort alone —
// a request sent without one is reported rather than left pending forever,
// which would hang this test file instead of failing it.
function stalls(options) {
  return new Promise((_, reject) => {
    if (!options.signal) {
      reject(new Error('the request was sent without a deadline and would never return'))
      return
    }
    // A deadline's own timer does not hold the Node event loop open, and here
    // nothing else is running, so the wait needs something that does.
    const alive = setInterval(() => {}, 5)
    options.signal.addEventListener('abort', () => { clearInterval(alive); reject(options.signal.reason) })
  })
}
async function run({ bodies = originals(), failPath, failAt, failure, failWrite, failWriteAt, writeFailure,
  hangPath, hangAt, hangWrite, hangInSeed, skip, callbackError } = {}) {
  const requests = [], callbacks = [], notes = [], deadlines = []
  const context = {
    ...helper, structuredClone, AbortSignal,
    process: { env: { GUIDE_SKIP_SEED: skip, AGENTHUB_GUIDE_REQUEST_TIMEOUT_MS: '50' } },
    document: { cookie: '' },
    page: { evaluate: (fn, args) => fn(args) },
    fetch: async (path, options) => {
      requests.push({ path, method: options.method, body: options.body && JSON.parse(options.body) })
      deadlines.push(Boolean(options.signal))
      if (options.method !== 'GET') {
        if (path === hangWrite) return await stalls(options)
        const writes = requests.filter(r => r.method !== 'GET').length
        const broken = (failWrite === undefined || path === failWrite) && (failWriteAt === undefined || writes === failWriteAt)
        if (broken && writeFailure === 'network') throw new Error('write disconnected')
        return { status: broken && writeFailure === 'http' ? 503 : 200, text: async () => '{}' }
      }
      if (path === hangInSeed) return await stalls(options)
      if (path === hangPath && (hangAt === undefined || requests.length === hangAt)) return await stalls(options)
      const fails = path === failPath && (failAt === undefined || requests.length === failAt)
      if (fails && failure === 'network') throw new Error('network disconnected')
      return { status: fails && failure === 'http' ? 503 : 200,
        text: async () => fails && failure === 'json' ? '{invalid' : JSON.stringify(bodies[paths.indexOf(path)]) }
    },
    note: (...args) => notes.push(args),
    seed: async (helpers) => {
      callbacks.push('seed')
      if (hangInSeed) await helpers.get(hangInSeed)
      if (callbackError === 'seed') throw new Error('seed failed')
    },
    capture: async () => { callbacks.push('capture'); if (callbackError === 'capture') throw new Error('capture failed') },
    captureTracking: async () => { callbacks.push('tracking'); if (callbackError === 'tracking') throw new Error('tracking failed') },
  }
  let error
  try { await vm.runInNewContext(`(async () => {${boundary}})()`, context) } catch (caught) { error = caught }
  return { requests, callbacks, notes, deadlines, error }
}
function blocked(result, reason) {
  assert.ok(result.error, 'must reject before work')
  assert.match(result.error.message, reason)
  assert.deepEqual(result.callbacks, [])
  assert.deepEqual(result.requests.filter(r => r.method !== 'GET'), [])
}
for (const [index, key] of keys.entries()) {
  for (const failure of ['http', 'network', 'json']) {
    test(`${key}: ${failure} blocks all writes and callbacks`, async () => {
      blocked(await run({ failPath: paths[index], failAt: index + 1, failure }), /503|network|JSON/i)
    })
  }
  for (const invalid of [undefined, null, [], 'invalid']) {
    test(`${key}: rejects ${JSON.stringify(invalid)}`, async () => {
      const bodies = originals()
      bodies[Math.min(index, 2)][key] = invalid
      blocked(await run({ bodies }), new RegExp(key === 'document' ? 'policy' : key === 'settings' ? 'dlp' : key))
    })
  }
}
for (const [name, change] of [
  ['missing rules', b => delete b[0].document.rules],
  ['null rules', b => { b[0].document.rules = null }],
  ['object rules', b => { b[0].document.rules = {} }],
  ['missing enabled', b => delete b[1].settings.enabled],
  ['string enabled', b => { b[1].settings.enabled = 'false' }],
  ['null classes', b => { b[1].settings.classes = null }],
  ['array classes', b => { b[1].settings.classes = [] }],
]) test(name, async () => { const bodies = originals(); change(bodies); blocked(await run({ bodies }), /policy|dlp/) })
for (const invalid of [null, [], 'invalid']) {
  for (const index of [0, 1, 2]) test(`invalid envelope ${index}: ${JSON.stringify(invalid)}`, async () => {
    const bodies = originals(); bodies[index] = invalid
    blocked(await run({ bodies }), /backup/)
  })
}
for (const callbackError of [undefined, 'seed', 'capture', 'tracking']) {
  test(`exact restoration after ${callbackError ?? 'success'}`, async () => {
    const bodies = originals()
    const result = await run({ bodies, callbackError })
    assert.equal(result.error?.message, callbackError && `${callbackError} failed`)
    const writes = result.requests.filter(r => r.method !== 'GET')
    assert.deepEqual(writes, [
      { method: 'PUT', path: paths[0], body: bodies[0].document },
      { method: 'PUT', path: paths[1], body: bodies[1].settings },
      { method: 'PUT', path: `${paths[2]}/sessionGateway`, body: { value: bodies[2].sessionGateway } },
      { method: 'PUT', path: `${paths[2]}/tracking`, body: { value: bodies[2].tracking } },
    ])
    if (!callbackError) assert.deepEqual(result.callbacks, ['seed', 'capture', 'tracking'])
  })
}
function restorations(bodies) {
  return [
    { method: 'PUT', path: paths[0], body: bodies[0].document },
    { method: 'PUT', path: paths[1], body: bodies[1].settings },
    { method: 'PUT', path: `${paths[2]}/sessionGateway`, body: { value: bodies[2].sessionGateway } },
    { method: 'PUT', path: `${paths[2]}/tracking`, body: { value: bodies[2].tracking } },
  ]
}
const failedNotes = result => result.notes.filter(([, ok]) => !ok).map(([label]) => label)
for (const writeFailure of ['network', 'http']) {
  test(`a ${writeFailure} failure on the first restoration still restores the other three`, async () => {
    const bodies = originals()
    const result = await run({ bodies, failWrite: paths[0], writeFailure })
    assert.deepEqual(result.requests.filter(r => r.method !== 'GET'), restorations(bodies))
    assert.deepEqual(failedNotes(result), [`복원 ${paths[0]}`])
    assert.match(result.error.message, new RegExp(`복원 실패.*${paths[0]}`))
  })
  test(`a ${writeFailure} failure on the third restoration still restores the fourth`, async () => {
    const bodies = originals()
    const result = await run({ bodies, failWrite: `${paths[2]}/sessionGateway`, writeFailure })
    assert.deepEqual(result.requests.filter(r => r.method !== 'GET'), restorations(bodies))
    assert.deepEqual(failedNotes(result), [`복원 ${paths[2]}/sessionGateway`])
    assert.match(result.error.message, /복원 실패.*sessionGateway/)
  })
  test(`every restoration failing (${writeFailure}) is attempted and reported`, async () => {
    const bodies = originals()
    const result = await run({ bodies, writeFailure })
    assert.deepEqual(result.requests.filter(r => r.method !== 'GET'), restorations(bodies))
    assert.deepEqual(failedNotes(result), restorations(bodies).map(w => `복원 ${w.path}`))
    assert.deepEqual(result.callbacks, ['seed', 'capture', 'tracking'])
  })
  for (const callbackError of ['seed', 'capture', 'tracking']) {
    test(`${callbackError} failure is thrown, not the ${writeFailure} restoration failure`, async () => {
      const bodies = originals()
      const result = await run({ bodies, callbackError, failWrite: paths[1], writeFailure })
      assert.equal(result.error?.message, `${callbackError} failed`)
      assert.deepEqual(result.requests.filter(r => r.method !== 'GET'), restorations(bodies))
      assert.deepEqual(failedNotes(result), [`복원 ${paths[1]}`])
    })
  }
}
test('optional DLP classes and empty setting objects are valid', async () => {
  const result = await run({ bodies: [{ document: { rules: [] } }, { settings: { enabled: false } }, { sessionGateway: {}, tracking: {} }] })
  assert.ifError(result.error)
  assert.equal(result.requests.filter(r => r.method === 'PUT').length, 4)
})
test('skip runs capture only without any backup or restoration', async () => {
  const result = await run({ skip: '1', failure: 'network', failPath: paths[0] })
  assert.ifError(result.error)
  assert.deepEqual(result.callbacks, ['capture'])
  assert.deepEqual(result.requests, [])
})
for (const throws of [false, true]) test(`backups are deep copies, callback throws: ${throws}`, async () => {
  assert.ok(helper.withGuideSettings, 'script must import the tested boundary')
  const bodies = originals(), expected = structuredClone(bodies), writes = []
  const work = helper.withGuideSettings(async (method, path, body) => {
    if (method === 'GET') return { status: 200, body: bodies[paths.indexOf(path)] }
    writes.push(body)
    return { status: 200 }
  }, { seed: async () => {
    bodies[0].document.rules[0].actions.push('changed')
    bodies[1].settings.classes.phone = 'block'
    bodies[2].sessionGateway.extra.list.push('changed')
    bodies[2].tracking.extra.list.push('changed')
    if (throws) throw new Error('work failed')
  }, capture: async () => {}, captureTracking: async () => {} })
